"""Ersetzt exakt (je genau 1 Treffer). Aufruf: python ersetze.py <regeln.json>
regeln.json: [{"datei": "...", "alt": "...", "neu": "..."}, ...]"""
import json, sys

regeln = json.load(open(sys.argv[1], encoding="utf-8"))
dateien = {}
for r in regeln:
    p = r["datei"]
    if p not in dateien:
        dateien[p] = open(p, encoding="utf-8").read()
    n = dateien[p].count(r["alt"])
    if n != 1:
        sys.exit(f"FEHLER {p}: {n} Treffer fuer: {r['alt'][:90]}")
    dateien[p] = dateien[p].replace(r["alt"], r["neu"])
for p, s in dateien.items():
    open(p, "w", encoding="utf-8", newline="").write(s)
    print("ok", p)

